'use strict';
// Scorer process only: expected labels never enter the provider process or its requests.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
const {create}=require('./objectivePredicateDiagnostic'),{packets,PIN,messages}=require('./objectiveElementaryActual72'),historical=require('./pricingDirectiveGroupsActualJudge');
const FILES={labels:['tests/release-inputs/objective-predicate-v2-elementary-independent-labels-2026-09-27.json','bafc6cdbadc5a06593f2ee0299e3a2eaaeaab43b1efca5e4f2a494cfa716170f'],seal:['tests/release-inputs/objective-predicate-v2-elementary-corrected-seal-2026-09-27.json','bdb7979093ccf336321345261d4c2ce5bc5c8ff35f83e3808ab12996c1bd29e2'],replacement:['tests/release-inputs/objective-predicate-v2-p35-replacement-label-review-2026-09-27.json','78a8cebeef3c1e39e4b4d12ab4d0c777e43d2ec112d2ba38b97605a157700d84']};
const sha=x=>createHash('sha256').update(x).digest('hex');
function labels(root,inputs){const read=key=>{const [file,pin]=FILES[key],bytes=fs.readFileSync(path.join(root,file));assert.equal(sha(bytes),pin);return JSON.parse(bytes);};const seal=read('seal'),declared=read('labels'),replacement=read('replacement');assert.equal(seal.successorInputSha256,PIN);assert.equal(seal.replacementLabelReview,'tasks/objective-predicate-v2-p35-replacement-label-review-2026-09-27.json');assert.equal(seal.replacementLabelReviewSha256,FILES.replacement[1]);assert.equal(replacement.successorInputSha256,PIN);assert.equal(replacement.id,'V2P35');assert.equal(declared.labels.length,72);const mapping=seal.scoring.source_candidate.runtimeToProvisionalFacet;assert.deepEqual(mapping,{candidate:'supported',none:'contradicted',unknown:'unknown'});const result=new Map();for(const row of declared.labels){assert(!result.has(row.id));const label=row.predicate==='source_candidate'?mapping[row.label]:row.label;assert(['supported','contradicted','unknown'].includes(label));result.set(row.id,{id:row.id,predicate:row.predicate,label,rawLabel:row.label});}assert(result.has(replacement.id));assert.equal(result.get(replacement.id).predicate,replacement.predicate);assert(['supported','contradicted','unknown'].includes(replacement.label));result.set(replacement.id,{id:replacement.id,predicate:replacement.predicate,label:replacement.label});for(const item of inputs)assert.equal(result.get(item.id)?.predicate,item.predicate);return {expected:result,mapping};}
async function score(kind,rows,inputs,expected,mapping){assert(['gate','final'].includes(kind));const count=kind==='gate'?6:72;assert.equal(rows.length,count);assert.deepEqual(rows.map(x=>x.id),inputs.slice(0,count).map(x=>x.id));const scores=[];for(let i=0;i<count;i++){const item=inputs[i],row=rows[i];assert.equal(row.stage,item.stage);assert.equal(row.predicate,item.predicate);const target=expected.get(item.id);assert.equal(target.predicate,item.predicate);let observed=null,valid=false;const result=row.result;
 if(row.technicalComplete===true&&result?.status==='observed'&&result.calls===1&&result.records?.length===1){const raw=result.records[0].response;assert.equal(row.wire?.length,1);const wire=row.wire[0];assert.equal(wire.caseId,item.id);assert.equal(wire.kind,'inference');assert.equal(wire.status,'returned');assert.equal(wire.httpStatus,200);assert.equal(sha(wire.request),wire.requestSha256);assert.equal(sha(wire.response),wire.responseSha256);assert.equal(historical.reconstruct(wire.response),raw);const request=JSON.parse(wire.request);assert.equal(request.model,historical.MODEL);assert.deepEqual(request.messages,messages(result.records[0].request));assert.deepEqual(request.format,result.records[0].request.schema);const parsed=await create(item.evidence).runStage(async()=>raw,{stage:item.stage,predicate:item.predicate,controlledCandidate:item.controlledCandidate});assert.equal(parsed.evidenceDigest,result.evidenceDigest);assert.deepEqual(parsed.records[0]?.request,result.records[0].request);assert.deepEqual(parsed.facet,result.facet);if(parsed.status==='observed'){if(item.stage==='source_candidate')observed=mapping[parsed.facet.status];else if(item.stage.endsWith('_fulfillment')){assert.equal(item.controlledCandidate.relation,'conjunction');assert.equal(item.controlledCandidate.conditions.length,1);assert.deepEqual(Object.keys(parsed.facet),['C0']);observed=parsed.facet.C0.answer;}else observed=parsed.facet;valid=['supported','contradicted','unknown'].includes(observed);}}
 scores.push({id:item.id,predicate:item.predicate,valid,observed,expected:target.label,match:valid&&observed===target.label});}
 return {continue:kind==='gate'&&scores.every(x=>x.match),semanticAccepted:kind==='final'&&scores.length===72&&scores.every(x=>x.match),scores};}
function main(){const root=process.cwd(),output=process.env.ELEMENTARY_SCORING_OUTPUT;assert(path.isAbsolute(output));const inputs=packets(root),sealed=labels(root,inputs);let busy=false;process.send({ready:true});process.on('message',async message=>{if(busy){process.exitCode=1;process.disconnect();return;}busy=true;try{assert(Number.isSafeInteger(message.sequence));assert(Buffer.byteLength(JSON.stringify(message))<8*1024*1024);const result=await score(message.kind,message.rows,inputs,sealed.expected,sealed.mapping);fs.writeFileSync(output+'.tmp',JSON.stringify({inputSha256:PIN,kind:message.kind,...result},null,2)+'\n',{mode:0o600});fs.renameSync(output+'.tmp',output);process.send({sequence:message.sequence,result:{continue:result.continue,semanticAccepted:result.semanticAccepted}});}catch{process.send({sequence:message?.sequence,result:{continue:false,semanticAccepted:false,error:'SCORING_UNAVAILABLE'}});}finally{busy=false;}});}
module.exports={score,labels,FILES};if(require.main===module)main();
